// --- the stub upstream ---

// qaTmdbReq is one upstream request the stub recorded.
type qaTmdbReq struct{ method, path, query, ua string }

// qaTmdbUpstream is the fake TMDB origin: the plugin's MELLIFERA_TMDB_UPSTREAM
// seam pins every fetch the server subprocess makes here, so the joint never
// touches the network. Every handler records first — unknown-path hits stay
// visible in the recording (the plan-discrimination evidence).
type qaTmdbUpstream struct {
	baseURL string
	srv     *httptest.Server
	mu      sync.Mutex
	seen    []qaTmdbReq
}

func qaTmdbStartUpstream(t *testing.T) *qaTmdbUpstream {
	t.Helper()
	s := &qaTmdbUpstream{}
	mux := http.NewServeMux()
	// EVERY request records before dispatch — unmatched paths are the
	// plan-discrimination evidence (a mux-level 404 never reaches the
	// handlers below), and each hit logs under -v for triage.
	recordAll := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			s.record(r)
			t.Logf("qaTmdb stub hit: %s %s?%s", r.Method, r.URL.Path, r.URL.RawQuery)
			next.ServeHTTP(w, r)
		})
	}
	mux.HandleFunc("/3/search/movie", func(w http.ResponseWriter, r *http.Request) {
		list, ok := qaTmdbMovieSearches[r.URL.Query().Get("query")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaTmdbWriteJSON(t, w, map[string]any{"results": list})
	})
	mux.HandleFunc("/3/search/tv", func(w http.ResponseWriter, r *http.Request) {
		list, ok := qaTmdbTVSearches[r.URL.Query().Get("query")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaTmdbWriteJSON(t, w, map[string]any{"results": list})
	})
	mux.HandleFunc("/3/movie/", func(w http.ResponseWriter, r *http.Request) {
		rest := strings.TrimPrefix(r.URL.Path, "/3/movie/")
		if detail := qaTmdbFilmByID(rest); detail != nil {
			qaTmdbWriteJSON(t, w, detail)
			return
		}
		if id := qaTmdbCreditsID(rest); id != 0 {
			qaTmdbWriteJSON(t, w, map[string]any{"cast": qaTmdbCredits[id]})
			return
		}
		http.NotFound(w, r)
	})
	mux.HandleFunc("/3/tv/", func(w http.ResponseWriter, r *http.Request) {
		rest := strings.TrimPrefix(r.URL.Path, "/3/tv/")
		switch rest {
		case strconv.Itoa(qaTmdbSeriesID):
			qaTmdbWriteJSON(t, w, qaTmdbSeriesDetail)
			return
		case strconv.Itoa(qaTmdbSeriesID) + "/season/2":
			qaTmdbWriteJSON(t, w, qaTmdbSeason2)
			return
		}
		http.NotFound(w, r)
	})
	s.srv = httptest.NewServer(recordAll(mux))
	// The seam value REPLACES the whole default base INCLUDING the version
	// prefix (defaultAPIBase is https://api.themoviedb.org/3), so the origin
	// handed to MELLIFERA_TMDB_UPSTREAM bakes /3 and the handlers above stay
	// under /3/... — the plugin composes apiBase + "/search/tv" etc.
	s.baseURL = s.srv.URL + "/3"
	t.Cleanup(s.srv.Close)
	return s
}

// recording renders the request journal compactly for failure messages.
func (s *qaTmdbUpstream) recording() string {
	reqs := s.requests()
	out := make([]string, 0, len(reqs))
	for _, r := range reqs {
		out = append(out, r.method+" "+r.path+"?"+r.query)
	}
	return strings.Join(out, " | ")
}

func (s *qaTmdbUpstream) record(r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seen = append(s.seen, qaTmdbReq{method: r.Method, path: r.URL.Path, query: r.URL.RawQuery, ua: r.Header.Get("User-Agent")})
}

// requests snapshots the recording.
func (s *qaTmdbUpstream) requests() []qaTmdbReq {
	s.mu.Lock()
	defer s.mu.Unlock()
	return append([]qaTmdbReq(nil), s.seen...)
}

// countPath counts recorded GETs whose path equals path.
func (s *qaTmdbUpstream) countPath(path string) int {
	n := 0
	for _, r := range s.requests() {
		if r.method == http.MethodGet && r.path == path {
			n++
		}
	}
	return n
}

// qaTmdbLastStageStatus returns the LAST _stages entry's status for plugin —
// _stages are append-only (a pre-identify "skipped" entry persists beside the
// post-identify "ok"), so the plugin's current outcome is its newest entry.
func qaTmdbLastStageStatus(stages []map[string]any, plugin string) string {
	last := ""
	for _, s := range stages {
		if asyncStr(s, "plugin_id") == plugin {
			last = asyncStr(s, "status")
		}
	}
	return last
}

// queryOf returns the recorded query of the FIRST hit of path ("" when none).
func (s *qaTmdbUpstream) queryOf(path string) string {
	for _, r := range s.requests() {
		if r.path == path {
			return r.query
		}
	}
	return ""
}

func qaTmdbWriteJSON(t *testing.T, w http.ResponseWriter, v any) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(v); err != nil {
		t.Errorf("stub write: %v", err)
	}
}

func qaTmdbFilmByID(rest string) map[string]any {
	switch rest {
	case strconv.Itoa(qaTmdbFilmAID):
		return qaTmdbFilmA
	case strconv.Itoa(qaTmdbFilmBID):
		return qaTmdbFilmB
	}
	return nil
}

// qaTmdbCreditsID reads the "{id}/credits" path form (0 when rest is not one).
func qaTmdbCreditsID(rest string) int {
	if !strings.HasSuffix(rest, "/credits") {
		return 0
	}
	id, err := strconv.Atoi(strings.TrimSuffix(rest, "/credits"))
	if err != nil {
		return 0
	}
	return id
}

