// qaTmdbStartServer builds the full binary set and starts the real server
// subprocess with the tmdb seam pinned (MELLIFERA_TMDB + MELLIFERA_TMDB_UPSTREAM
// through qaSerialServerBins — the plugin child inherits the server env, so
// every fetch template bakes the stub origin).
func qaTmdbStartServer(t *testing.T, tmp, tmdbUpstream, shikimoriUpstream string) qaSerialServer {
	t.Helper()
	bins := qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-tmdb-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-tmdb-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-tmdb-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-tmdb-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-tmdb-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-tmdb-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-tmdb-grabber", "./plugins/frame-grabber"),
		tmdb:          buildBinary(t, tmp, "qa-tmdb", "./plugins/tmdb"),
		tmdbUpstream:  tmdbUpstream,
	}
	return qaSerialStartServer(t, bins, shikimoriUpstream, tmp, qaTmdbToken)
}

