// qaTmdbConfigureSecret writes the api key through the REAL options write
// (tmdb-enrichment 3.2): PUT /admin/modules/{module}/sources/tmdb/options.
// An ordinary key rides along so the serve-side redaction law's positive half
// is exercised everywhere the aggregate is read (ordinary keys verbatim, the
// declared secret omitted).
func qaTmdbConfigureSecret(t *testing.T, c *http.Client, baseURL, moduleID string) {
	t.Helper()
	body := map[string]any{"options": map[string]any{"api_key": qaTmdbAPIKey, "language": "en-US"}}
	var ignored map[string]any
	if status := doRequest(t, c, http.MethodPut, baseURL+"/api/v1/admin/modules/"+moduleID+"/sources/tmdb/options", qaTmdbToken, body, &ignored); status != http.StatusNoContent {
		t.Fatalf("PUT options (%s/tmdb): HTTP %d, want 204", moduleID, status)
	}
}

// qaTmdbSearch searches the passthrough (GET /admin/sources/tmdb/search) and
// returns the status, the candidates, and the canonical error code — the raw
// error body rides the fatal message on a non-200 (the upstream-class
// evidence).
func qaTmdbSearch(t *testing.T, c *http.Client, baseURL, query, kind string) ([]map[string]any, int, string) {
	t.Helper()
	u := baseURL + "/api/v1/admin/sources/tmdb/search?query=" + url.QueryEscape(query)
	if kind != "" {
		u += "&kind=" + url.QueryEscape(kind)
	}
	req, err := http.NewRequest(http.MethodGet, u, nil)
	if err != nil {
		t.Fatalf("search request: %v", err)
	}
	req.Header.Set("Authorization", "Bearer "+qaTmdbToken)
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("search: %v", err)
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("search body: %v", err)
	}
	var shaped struct {
		Candidates []map[string]any `json:"candidates"`
		Error      struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(raw, &shaped); err != nil && resp.StatusCode == http.StatusOK {
		t.Fatalf("search 200 body %s: decode: %v", raw, err)
	}
	if resp.StatusCode != http.StatusOK {
		t.Logf("search HTTP %d body: %s", resp.StatusCode, raw)
	}
	return shaped.Candidates, resp.StatusCode, shaped.Error.Code
}

// qaTmdbIdentify drives the identify write over either row space; it returns
// the 202 queued flag and, on a non-202, the canonical error code.
func qaTmdbIdentify(t *testing.T, c *http.Client, baseURL, space, rowID, externalID string) (queued bool, status int, errCode string) {
	t.Helper()
	body := map[string]any{"source_id": "tmdb", "external_id": externalID}
	var resp struct {
		Queued   bool `json:"queued"`
		Stripped int  `json:"stripped"`
		Deferred int  `json:"deferred"`
		Error    struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	status = doRequest(t, c, http.MethodPut, baseURL+"/api/v1/"+space+"/"+rowID+"/identify", qaTmdbToken, body, &resp)
	return resp.Queued, status, resp.Error.Code
}

// qaTmdbItemDTO is the QA-local decode of the served item wire shape (the api
// itemDTO with its additive convention metadata block).
type qaTmdbItemDTO struct {
	ID           string          `json:"id"`
	RelativePath string          `json:"relative_path"`
	MediaType    string          `json:"media_type"`
	Document     json.RawMessage `json:"document"`
	Status       string          `json:"status"`
	Metadata     map[string]any  `json:"metadata"`
}

// qaTmdbListItems decodes a library's items WITH the metadata block.
func qaTmdbListItems(t *testing.T, c *http.Client, baseURL string, libID int64) []qaTmdbItemDTO {
	t.Helper()
	var resp struct {
		Items []qaTmdbItemDTO `json:"items"`
	}
	u := baseURL + "/api/v1/items?library=" + strconv.FormatInt(libID, 10) + "&limit=200"
	if status := doRequest(t, c, http.MethodGet, u, qaTmdbToken, nil, &resp); status != http.StatusOK {
		t.Fatalf("list items lib %d: HTTP %d, want 200", libID, status)
	}
	return resp.Items
}

func qaTmdbItemByRel(t *testing.T, c *http.Client, baseURL, token string, libID int64, rel string) qaTmdbItemDTO {
	t.Helper()
	for _, it := range qaTmdbListItems(t, c, baseURL, libID) {
		if it.RelativePath == rel {
			return it
		}
	}
	t.Fatalf("item %q not persisted in lib %d", rel, libID)
	return qaTmdbItemDTO{}
}

// qaTmdbWaitItemNamespace polls until the item's document carries
// sources.tmdb (bounded — an identify whose tmdb run soft-failed would settle
// ready with NO namespace, and that must fail this wait, never bless it). The
// stub rides along so the fatal message carries the recorded upstream requests
// — the plan-discrimination evidence next to the stage failure.
func qaTmdbWaitItemNamespace(t *testing.T, c *http.Client, baseURL string, libID int64, rel string, up *qaTmdbUpstream) qaTmdbItemDTO {
	t.Helper()
	// One identify = one derivation run over seconds; 30s is >4x the observed
	// settle time and far under the stale-suite 90s drain bound.
	deadline := time.Now().Add(30 * time.Second)
	var last qaTmdbItemDTO
	for time.Now().Before(deadline) {
		for _, it := range qaTmdbListItems(t, c, baseURL, libID) {
			if it.RelativePath != rel {
				continue
			}
			last = it
			doc := parseAsyncDoc(t, it.Document)
			if _, ok := doc.Sources["tmdb"]; ok {
				return it
			}
		}
		time.Sleep(probeInterval)
	}
	rec := ""
	if up != nil {
		rec = " (upstream recording: " + up.recording() + ")"
	}
	t.Fatalf("item %q never grew sources.tmdb within 30s%s (last doc: %s)", rel, rec, last.Document)
	return qaTmdbItemDTO{}
}

// qaTmdbWaitSeriesNamespace polls a SERIAL-module series' BY-ID document until
// it carries sources.tmdb. The serial module serves series records through
// /api/v1/series/{id} — the generic /items listing never surfaces the series
// row (observed: the row never matched its rel in the listing), so the generic
// waiter cannot see the commit. Non-200s during the poll are skipped (the
// identify strip/rebuild window), not fatal — only the timeout fatal carries
// the upstream recording next to the last doc.
func qaTmdbWaitSeriesNamespace(t *testing.T, c *http.Client, baseURL, token, seriesID string, up *qaTmdbUpstream) json.RawMessage {
	t.Helper()
	deadline := time.Now().Add(30 * time.Second)
	var last json.RawMessage
	for time.Now().Before(deadline) {
		if sr, status, _ := qaSerialGetSeries(t, c, baseURL, token, seriesID); status == http.StatusOK {
			last = sr.Document
			if doc := parseAsyncDoc(t, sr.Document); doc.Sources != nil {
				if _, ok := doc.Sources["tmdb"]; ok {
					return sr.Document
				}
			}
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("series %s never grew sources.tmdb within 30s (upstream recording: %s) (last doc: %s)",
		seriesID, up.recording(), last)
	return nil
}

// qaTmdbWaitEpisodeRoutes polls until BOTH episode items carry sources.tmdb
// (the routing lands AFTER the series run's own namespace is committed, so a
// series-namespace observation never implies the episode writes landed).
func qaTmdbWaitEpisodeRoutes(t *testing.T, c *http.Client, baseURL string, libID int64, rels []string) []qaTmdbItemDTO {
	t.Helper()
	want := map[string]bool{}
	for _, rel := range rels {
		want[rel] = true
	}
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		got := map[string]qaTmdbItemDTO{}
		for _, it := range qaTmdbListItems(t, c, baseURL, libID) {
			if !want[it.RelativePath] {
				continue
			}
			doc := parseAsyncDoc(t, it.Document)
			if _, ok := doc.Sources["tmdb"]; ok {
				got[it.RelativePath] = it
			}
		}
		if len(got) == len(rels) {
			out := make([]qaTmdbItemDTO, 0, len(rels))
			for _, rel := range rels {
				out = append(out, got[rel])
			}
			return out
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("episode routes never landed on %v within %s", rels, qaSerialDrainTimeout)
	return nil
}

// qaTmdbWaitTmdbFailure polls the failure ledger until a (rowID, tmdb) row is
// present, returning it (the relay handoff's durable trace).
func qaTmdbWaitTmdbFailure(t *testing.T, c *http.Client, baseURL, rowID string) qaRelayFailureRow {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	var resp qaRelayFailures
	for time.Now().Before(deadline) {
		if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/enrich/failures", qaTmdbToken, nil, &resp); status != http.StatusOK {
			t.Fatalf("GET /enrich/failures: HTTP %d, want 200", status)
		}
		for _, f := range resp.Failures {
			if f.RowID == rowID && f.PluginID == "tmdb" {
				return f
			}
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("tmdb failure row for %s never landed within %s (failures: %+v)", rowID, qaSerialDrainTimeout, resp.Failures)
	return qaRelayFailureRow{}
}

// qaTmdbBinding is one metadata binding row of the GET /admin/plugins
// aggregate (the pluginAdminBinding wire shape).
type qaTmdbBinding struct {
	ModuleID        string          `json:"module_id"`
	Kind            string          `json:"kind"`
	Priority        *int            `json:"priority"`
	Enabled         *bool           `json:"enabled"`
	AuthMode        string          `json:"auth_mode"`
	Options         json.RawMessage `json:"options"`
	RequiredSecrets map[string]bool `json:"required_secrets"`
}

// qaTmdbBindingFor reads the tmdb plugin's binding row for moduleID from the
// aggregate.
func qaTmdbBindingFor(t *testing.T, c *http.Client, baseURL, moduleID string) qaTmdbBinding {
	t.Helper()
	var resp struct {
		Plugins []struct {
			PluginID string          `json:"plugin_id"`
			Config   []qaTmdbBinding `json:"config"`
		} `json:"plugins"`
	}
	if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/admin/plugins", qaTmdbToken, nil, &resp); status != http.StatusOK {
		t.Fatalf("GET /admin/plugins: HTTP %d, want 200", status)
	}
	for _, p := range resp.Plugins {
		if p.PluginID != "tmdb" {
			continue
		}
		for _, b := range p.Config {
			if b.ModuleID == moduleID && b.Kind == "metadata" {
				return b
			}
		}
	}
	t.Fatalf("aggregate carries no tmdb metadata binding for module %q (plugins: %+v)", moduleID, resp.Plugins)
	return qaTmdbBinding{}
}

// qaTmdbWriteFilmLibrary writes one film file into a fresh library root.
func qaTmdbWriteFilmLibrary(t *testing.T, rel string) string {
	t.Helper()
	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, rel))
	return root
}

// decodeMap reads one top-level JSON object field from a raw document.
func decodeMap(raw json.RawMessage, key string) (map[string]any, error) {
	var full map[string]any
	if err := json.Unmarshal(raw, &full); err != nil {
		return nil, err
	}
	m, _ := full[key].(map[string]any)
	return m, nil
}

// --- leg (a): film enrichment end to end ---

// TestQATmdbFilmEnrichmentJoint: tv-library film → REAL options write →
// search passthrough → item identify → anchored /movie/{id} + /credits run →
// sources.tmdb → the served about + cast blocks. The stub's recording proves
// the substitution seam (the api_key literal arrives core-resolved) and the
// anchored plan's shape (detail + credits extra, by id, never a search).
func TestQATmdbFilmEnrichmentJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tmdb joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the film fixture cannot be probed (INV4: optional binary)")
	}
	tmp := t.TempDir()
	up := qaTmdbStartUpstream(t)
	srv := qaTmdbStartServer(t, tmp, up.baseURL, qaTmdbDeadUpstream)
	client := &http.Client{Timeout: httpTimeout}

	// 3.1's method: the secret configured through the REAL options write.
	qaTmdbConfigureSecret(t, client, srv.baseURL, "tv")

	// The enrichment spine first: scan → pre-identify pins → identify → the
	// anchored run → the served blocks. The search-passthrough contract
	// (SearchSpecs → core-executed fetch with the resolved secret →
	// SearchResults in served order) asserts at the END so the leg reports
	// every defect it finds, not just the first.
	root := qaTmdbWriteFilmLibrary(t, qaTmdbFilmARel)
	libID := qaTmdbCreateTvLibrary(t, client, srv.baseURL, root, "QA Tmdb Film")
	res := scanLibrary(t, client, srv.baseURL, qaTmdbToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("film scan discovered=%d persisted=%d, want 1/1; warnings=%v", res.Discovered, res.Persisted, res.Warnings)
	}
	qaSerialWaitSettled(t, client, srv.baseURL, qaTmdbToken, libID)
	before := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, qaTmdbFilmARel)
	beforeDoc := parseAsyncDoc(t, before.Document)
	if _, present := beforeDoc.Sources["tmdb"]; present {
		t.Fatalf("unanchored film carries sources.tmdb = %v before any identify (the anchor is the only route)", beforeDoc.Sources["tmdb"])
	}
	if !asyncStageHas(beforeDoc.Stages, "tmdb", "skipped") {
		t.Errorf("unanchored film _stages = %v, want a skipped tmdb stage (no title fact, no anchor)", beforeDoc.Stages)
	}

	// The identify write: the operator anchors the searched candidate's id.
	queued, st, idCode := qaTmdbIdentify(t, client, srv.baseURL, "items", before.ID, strconv.Itoa(qaTmdbFilmAID))
	if st != http.StatusAccepted || !queued {
		t.Fatalf("identify: HTTP %d queued=%v (%s), want 202 queued=true", st, queued, idCode)
	}

	// The anchored run: /movie/{id} primary + /credits extra, by id, never a
	// search — then the namespace lands.
	it := qaTmdbWaitItemNamespace(t, client, srv.baseURL, libID, qaTmdbFilmARel, up)
	doc := parseAsyncDoc(t, it.Document)
	// _stages are APPEND-ONLY: the pre-identify "skipped" entry legitimately
	// persists beside the post-identify run, so the identified outcome is the
	// plugin's LAST entry — it must be ok.
	if last := qaTmdbLastStageStatus(doc.Stages, "tmdb"); last != "ok" {
		t.Errorf("identified film's last tmdb stage = %q, want ok (append-only stages: %v)", last, doc.Stages)
	}
	tmdb := doc.Sources["tmdb"]
	ids, _ := decodeMap(it.Document, "identifiers")
	if got := asyncInt(ids, "tmdb_id"); got != qaTmdbFilmAID {
		t.Errorf("identifiers.tmdb_id = %v, want %d (the picked anchor)", ids["tmdb_id"], qaTmdbFilmAID)
	}
	title, _ := tmdb["title"].(map[string]any)
	if asyncStr(title, "russian") != "Ночной бег" || asyncStr(title, "romaji") != "Night Run" {
		t.Errorf("sources.tmdb.title = %v, want the RU-first pair from the stub payload", title)
	}
	if asyncStr(tmdb, "description") != "qa film A synopsis — ночной бег через спящий город." ||
		asyncStr(tmdb, "kind") != "movie" || asyncStr(tmdb, "aired_on") != "2019-03-14" {
		t.Errorf("sources.tmdb = %v, want the stub's description/kind/aired_on verbatim", tmdb)
	}
	if got := asyncInt(tmdb, "episodes"); got != -1 {
		t.Errorf("sources.tmdb.episodes = %v, want absent (honest absence: the movie payload carries none)", tmdb["episodes"])
	}
	if asyncStr(tmdb, "poster") != "https://image.tmdb.org/t/p/original/qaPosterA.jpg" ||
		asyncStr(tmdb, "url") != "https://www.themoviedb.org/movie/700101" {
		t.Errorf("sources.tmdb poster/url = %v/%v, want the composed absolute URLs", tmdb["poster"], tmdb["url"])
	}
	cast, _ := tmdb["cast"].([]any)
	if len(cast) != 1 {
		t.Fatalf("sources.tmdb.cast = %v, want exactly the credits stub's one entry", cast)
	}
	entry, _ := cast[0].(map[string]any)
	if asyncStr(entry, "name") != "Иван Qa Актёров" || asyncStr(entry, "role") != "Машинист" ||
		asyncStr(entry, "photo_url") != "https://image.tmdb.org/t/p/original/qaFaceA.jpg" {
		t.Errorf("cast entry = %v, want {name, role, photo_url composed absolute}", entry)
	}
	if pid := asyncStr(doc.Provenance["description"], "plugin_id"); pid != "tmdb" {
		t.Errorf("_provenance.description.plugin_id = %q, want tmdb (the core's authoritative stamp)", pid)
	}

	// The anchored plan's shape at the stub: exactly the detail + credits pair
	// under the resolved key — and the search endpoint never re-fired.
	if up.countPath("/3/movie/700101") != 1 || up.countPath("/3/movie/700101/credits") != 1 {
		t.Errorf("anchored run fetches: /3/movie/700101 x%d, /credits x%d, want exactly one of each",
			up.countPath("/3/movie/700101"), up.countPath("/3/movie/700101/credits"))
	}
	detailQuery := up.queryOf("/3/movie/700101")
	if !strings.Contains(detailQuery, "api_key="+qaTmdbAPIKey) || !strings.Contains(detailQuery, "language=ru-RU") {
		t.Errorf("detail fetch query = %q, want the resolved key + RU-first language", detailQuery)
	}

	// The served projection: the about + cast blocks over the item wire.
	served := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, qaTmdbFilmARel)
	about, _ := served.Metadata["about"].(map[string]any)
	if about == nil || asyncStr(about, "source") != "tmdb" ||
		asyncStr(about, "description") != "qa film A synopsis — ночной бег через спящий город." {
		t.Errorf("served metadata.about = %v, want the tmdb carrier with the stub description", served.Metadata["about"])
	}
	if kind, _ := about["kind"].(string); kind != "movie" {
		t.Errorf("served about.kind = %v, want movie (the ride-along fact)", about["kind"])
	}
	servedCast, _ := served.Metadata["cast"].([]any)
	if len(servedCast) != 1 {
		t.Errorf("served metadata.cast = %v, want the tmdb cast group verbatim", served.Metadata["cast"])
	}

	// The aggregate (3.3's live surface): the verdicts flipped with the stored
	// bytes, and the served options REDACT the declared secret while ordinary
	// keys ride verbatim — presence lives in the verdicts, never in the bytes.
	binding := qaTmdbBindingFor(t, client, srv.baseURL, "tv")
	if !binding.RequiredSecrets["api_key"] {
		t.Errorf("tv binding required_secrets = %v, want api_key provided:true after the options write", binding.RequiredSecrets)
	}
	if binding.AuthMode != "SERVER" {
		t.Errorf("tv binding auth_mode = %q, want SERVER (the seeded slot)", binding.AuthMode)
	}
	var opts map[string]any
	if err := json.Unmarshal(binding.Options, &opts); err != nil {
		t.Fatalf("tv binding served options %s: decode: %v", binding.Options, err)
	}
	if _, leak := opts["api_key"]; leak {
		t.Errorf("tv binding served options %v carry the raw api_key — the redaction law leaked", opts)
	}
	if opts["language"] != "en-US" {
		t.Errorf("tv binding served options = %v, want the ordinary key served verbatim (language en-US)", opts)
	}

	// The search passthrough, last (hard assertions): the overlay's
	// interactive leg against the REAL chain — SearchSpecs, the core-executed
	// fetch with the RESOLVED secret, SearchResults in served order.
	cands, status, errCode := qaTmdbSearch(t, client, srv.baseURL, "Night Run", "")
	if status != http.StatusOK {
		t.Errorf("search: HTTP %d (%s), want 200", status, errCode)
	} else {
		if len(cands) != 1 {
			t.Errorf("search candidates = %v, want exactly the stub's one candidate", cands)
		} else {
			c := cands[0]
			if c["external_id"] != strconv.Itoa(qaTmdbFilmAID) || c["title"] != "Night Run" ||
				c["russian_title"] != "Ночной бег" || c["kind"] != "movie" {
				t.Errorf("search candidate = %v, want the stub film A projection (external_id/title/russian_title/kind)", c)
			}
			if c["year"] == nil {
				t.Errorf("search candidate = %v, want the release-date-derived year", c)
			}
		}
	}
	// The substitution proof at the stub: the search fetch carried the RU-first
	// language and the RESOLVED api key — the literal can only have come from
	// the core-side resolveVariables over the binding options.
	q := up.queryOf("/3/search/movie")
	for _, part := range []string{"language=ru-RU", "api_key=" + qaTmdbAPIKey} {
		if !strings.Contains(q, part) {
			t.Errorf("search fetch query = %q, want it to carry %q (the resolved-secret substitution)", q, part)
		}
	}
}

// --- leg (b): the anchored series plan's season contributions ---

// TestQATmdbEpisodeTitlesJoint: a serial-library series identified to a tmdb
// id. CONTRACT (the async-enrichment delta, "An anchored series plan carries
// the season extra" + the episode routing scenario): the anchored run's query
// carries the document's own season fact (here season 2 — the serial-parser
// namespace value, the same fact the router reads at
// internal/enrich/episode_titles.go:227), BuildRequest composes the tv-detail
// primary PLUS the season extra, and the season payload's contributions land
// on the episode documents carrying title AND description.
//
// A red here whose recording shows /3/movie/{id} instead of the tv+season pair
// is NOT a test bug: it is the parsed-only season seam — plugins/tmdb/
// source.go:75 reads the season from req.GetItem().GetParsed() while no real
// series document ever carries a season in parsed (the scanner's stamp carries
// none; applyContribution never writes parsed; the serial-parser namespace is
// the season's only home, and reconstructBase (worker.go:135) feeds Match
// parsed alone). That is a product defect — HALT and report, never a test fix.
func TestQATmdbEpisodeTitlesJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tmdb joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the episode fixtures cannot be probed (INV4: optional binary)")
	}
	tmp := t.TempDir()
	up := qaTmdbStartUpstream(t)
	shiki := qaTmdbStartShikimoriStub(t)
	srv := qaTmdbStartServer(t, tmp, up.baseURL, shiki)
	client := &http.Client{Timeout: httpTimeout}

	// The SERIAL binding's options carry the secret — the per-binding home
	// (the same plugin bound by two modules with independent options).
	qaTmdbConfigureSecret(t, client, srv.baseURL, "serial")

	// Fixtures: one series directory at season 2 with two episodes.
	root := t.TempDir()
	qaSerialMedia(t, filepath.Join(root, qaTmdbSerialEp1Rel))
	qaSerialMedia(t, filepath.Join(root, qaTmdbSerialEp2Rel))
	libID := qaSerialCreateLibrary(t, client, srv.baseURL, qaTmdbToken, root, "QA Tmdb Serial")
	res := scanLibrary(t, client, srv.baseURL, qaTmdbToken, libID)
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("serial scan discovered=%d persisted=%d, want 3/3 (1 series record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	qaSerialWaitSettled(t, client, srv.baseURL, qaTmdbToken, libID)

	series := qaSerialListSeries(t, client, srv.baseURL, qaTmdbToken, libID)
	if len(series) != 1 || series[0].RelativePath != qaTmdbSerialDir {
		t.Fatalf("series rows = %v, want exactly %q", qaSerialRels(series), qaTmdbSerialDir)
	}
	sr := series[0]

	// The pre-identify reality pin: the bare serial record skips tmdb (no
	// display title in its parsed stamp), the serial-parser namespace owns the
	// season fact, and the episodes carry their parse facts.
	baseDoc := parseAsyncDoc(t, qaSerialSeriesDocument(t, client, srv.baseURL, qaTmdbToken, sr.ID))
	if _, present := baseDoc.Sources["tmdb"]; present {
		t.Fatalf("pre-identify series carries sources.tmdb: %v (a bare serial record must skip)", baseDoc.Sources["tmdb"])
	}
	if got := asyncInt(baseDoc.Sources["serial-parser"], "season"); got != 2 {
		t.Fatalf("serial-parser season = %v, want 2 (the fixture's marker) — the document's season fact", baseDoc.Sources["serial-parser"])
	}
	episodes := qaSerialSeriesEpisodeRels(t, client, srv.baseURL, qaTmdbToken, sr.ID)
	if len(episodes) != 2 || episodes[qaTmdbSerialEp1Rel] == "" || episodes[qaTmdbSerialEp2Rel] == "" {
		t.Fatalf("series episodes = %v, want exactly the two fixture episodes", qaSerialMapKeys(episodes))
	}

	// The identify write re-anchors the series row (the operator's picked id;
	// the tv-search passthrough this pick rides asserts at the leg's end so a
	// passthrough defect never masks the routing contract).
	queued, st, _ := qaTmdbIdentify(t, client, srv.baseURL, "series", sr.ID, strconv.Itoa(qaTmdbSeriesID))
	if st != http.StatusAccepted || !queued {
		t.Fatalf("series identify: HTTP %d queued=%v, want 202 queued=true", st, queued)
	}

	// CONTRACT assertion 1 — the anchored SERIES plan at the stub: the
	// tv-detail primary PLUS the season extra at the document's own season 2,
	// and NO movie-path fetch for the series anchor. The plan runs within
	// seconds of the identify; 30s bounds the observation window.
	seriesIDPath := "/3/tv/" + strconv.Itoa(qaTmdbSeriesID)
	seasonPath := seriesIDPath + "/season/2"
	// BOTH wire events before any counting: the season extra paces ~250ms
	// behind the primary (the tmdb FetchGate slot), so counting at the
	// primary's first hit races the plan's own tail.
	deadline := time.Now().Add(30 * time.Second)
	for time.Now().Before(deadline) && (up.countPath(seriesIDPath) == 0 || up.countPath(seasonPath) == 0) {
		time.Sleep(probeInterval)
	}
	if up.countPath(seriesIDPath) != 1 {
		t.Errorf("anchored series run: %s x%d, want exactly the tv-detail primary; recording: %s",
			seriesIDPath, up.countPath(seriesIDPath), up.recording())
	}
	if up.countPath(seasonPath) != 1 {
		// The season extra at the DOCUMENT's own season — the contract's whole
		// point. A /3/movie/{id} here means the anchored query lost the
		// season fact (the parsed-only seam — see the function comment).
		t.Errorf("anchored series run: %s x%d, want exactly the season extra; recording: %s",
			seasonPath, up.countPath(seasonPath), up.recording())
	}
	if up.countPath("/3/movie/"+strconv.Itoa(qaTmdbSeriesID)) != 0 {
		t.Errorf("anchored series run fetched /3/movie/%d — the MOVIE plan ran for a series anchor (plan discrimination broke)",
			qaTmdbSeriesID)
	}
	seasonQuery := up.queryOf(seasonPath)
	if seasonQuery != "" && (!strings.Contains(seasonQuery, "api_key="+qaTmdbAPIKey) || !strings.Contains(seasonQuery, "language=ru-RU")) {
		t.Errorf("season fetch query = %q, want the resolved key + RU-first language", seasonQuery)
	}

	// The series namespace: the tv detail's RU-first projection — waited for
	// on the series' BY-ID document, never raced (the commit follows the
	// season extra and the merge).
	seriesRaw := qaTmdbWaitSeriesNamespace(t, client, srv.baseURL, qaTmdbToken, sr.ID, up)
	seriesDoc := parseAsyncDoc(t, seriesRaw)
	stmdb := seriesDoc.Sources["tmdb"]
	if stmdb == nil {
		t.Fatalf("identified series carries no sources.tmdb (stages %v)", seriesDoc.Stages)
	}
	stitle, _ := stmdb["title"].(map[string]any)
	if asyncStr(stitle, "russian") != "Северный маршрут" || asyncStr(stitle, "romaji") != "Northern Route" {
		t.Errorf("sources.tmdb.title = %v, want the tv stub's RU-first pair", stitle)
	}
	if asyncStr(stmdb, "kind") != "tv" || asyncInt(stmdb, "episodes") != 8 {
		t.Errorf("sources.tmdb kind/episodes = %v/%v, want tv/8", stmdb["kind"], stmdb["episodes"])
	}
	ids, _ := decodeMap(seriesRaw, "identifiers")
	if got := asyncInt(ids, "tmdb_id"); got != qaTmdbSeriesID {
		t.Errorf("identifiers.tmdb_id = %v, want %d", ids["tmdb_id"], qaTmdbSeriesID)
	}

	// CONTRACT assertion 2 — the routed contributions: the season payload's
	// entries land on the matching episode documents with title AND
	// description, stamped tmdb.
	routed := qaTmdbWaitEpisodeRoutes(t, client, srv.baseURL, libID, []string{qaTmdbSerialEp1Rel, qaTmdbSerialEp2Rel})
	wantTitles := map[string]string{
		qaTmdbSerialEp1Rel: "Первая вылазка",
		qaTmdbSerialEp2Rel: "Вторая вылазка",
	}
	for _, ep := range routed {
		doc := parseAsyncDoc(t, ep.Document)
		etmdb := doc.Sources["tmdb"]
		if etmdb == nil {
			t.Errorf("%q: no routed sources.tmdb", ep.RelativePath)
			continue
		}
		want := wantTitles[ep.RelativePath]
		if asyncStr(etmdb, "title") != want || asyncStr(etmdb, "description") == "" {
			t.Errorf("%q: routed sources.tmdb = %v, want title %q AND a description", ep.RelativePath, etmdb, want)
		}
		if pid := asyncStr(doc.Provenance["title"], "plugin_id"); pid != "tmdb" {
			t.Errorf("%q: _provenance.title.plugin_id = %q, want tmdb (the routed stamp)", ep.RelativePath, pid)
		}
	}

	// The served projection: each episode's own convention episode block.
	for _, ep := range qaTmdbListItems(t, client, srv.baseURL, libID) {
		want, isEp := wantTitles[ep.RelativePath]
		if !isEp {
			continue
		}
		episodeBlock, _ := ep.Metadata["episode"].(map[string]any)
		if episodeBlock == nil || asyncStr(episodeBlock, "title") != want || asyncStr(episodeBlock, "description") == "" {
			t.Errorf("served %q metadata.episode = %v, want {title %q, description}", ep.RelativePath, ep.Metadata["episode"], want)
		}
	}

	// The tv-search passthrough, last (hard assertions): kind=tv routes the
	// passthrough to the tv search endpoint, and the candidate projection
	// carries the tv facts.
	cands, status, errCode := qaTmdbSearch(t, client, srv.baseURL, qaTmdbShikimoriQuery, "tv")
	if status != http.StatusOK {
		t.Errorf("tv search: HTTP %d (%s), want 200", status, errCode)
	} else if len(cands) != 1 || cands[0]["external_id"] != strconv.Itoa(qaTmdbSeriesID) || cands[0]["kind"] != "tv" {
		t.Errorf("tv search candidates = %v, want the stub series (external_id %d, kind tv)", cands, qaTmdbSeriesID)
	}
}

// --- leg (c): the unconfigured binding is dormant and visible ---

// TestQATmdbUnconfiguredDormantJoint: no secret anywhere — the derivation
// derives nothing (no fetch, no ledger row, no namespace), the interactive
// surfaces answer the canonical 503 with nothing written, and the aggregate
// carries the provided:false verdict (OQ-5's "needs config" state). The
// upstream is pinned to the dead port so a dormancy bug that still fetched
// would surface as a network-class ledger row this leg asserts absent.
func TestQATmdbUnconfiguredDormantJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tmdb joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the film fixture cannot be probed (INV4: optional binary)")
	}
	tmp := t.TempDir()
	srv := qaTmdbStartServer(t, tmp, qaTmdbDeadUpstream, qaTmdbDeadUpstream)
	client := &http.Client{Timeout: httpTimeout}

	root := qaTmdbWriteFilmLibrary(t, "Dormant Signal 2021.mkv")
	libID := qaTmdbCreateTvLibrary(t, client, srv.baseURL, root, "QA Tmdb Dormant")
	res := scanLibrary(t, client, srv.baseURL, qaTmdbToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("dormant scan discovered=%d persisted=%d, want 1/1", res.Discovered, res.Persisted)
	}
	qaSerialWaitSettled(t, client, srv.baseURL, qaTmdbToken, libID)

	// Derivation dormancy: the row settled ready with NO tmdb namespace, NO
	// tmdb stage at all (2.3's queueability conjunct removes the source from
	// the chain before any attempt — dormancy is absence, not a skipped run),
	// and NO ledger row exists for tmdb (dormant is not a failure).
	it := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, "Dormant Signal 2021.mkv")
	if it.Status != "ready" {
		t.Errorf("dormant film status = %q, want ready (dormancy never stalls the row)", it.Status)
	}
	doc := parseAsyncDoc(t, it.Document)
	if _, present := doc.Sources["tmdb"]; present {
		t.Errorf("dormant film carries sources.tmdb = %v, want none", doc.Sources["tmdb"])
	}
	for _, s := range doc.Stages {
		if s["plugin_id"] == "tmdb" {
			t.Errorf("dormant film _stages carry a tmdb entry: %v (the unconfigured source must never be attempted)", s)
		}
	}
	var ledger qaRelayFailures
	if status := doRequest(t, client, http.MethodGet, srv.baseURL+"/api/v1/enrich/failures", qaTmdbToken, nil, &ledger); status != http.StatusOK {
		t.Fatalf("GET /enrich/failures: HTTP %d, want 200", status)
	}
	for _, f := range ledger.Failures {
		if f.PluginID == "tmdb" {
			t.Errorf("dormant binding left a ledger row: %+v (unconfigured is dormant, not failed)", f)
		}
	}

	// The search passthrough answers the canonical 503 — the missing-config
	// meaning, never a misleading 502 upstream_error.
	_, st, errCode := qaTmdbSearch(t, client, srv.baseURL, "Dormant Signal", "")
	if st != http.StatusServiceUnavailable || errCode != "unavailable" {
		t.Errorf("dormant search: HTTP %d code %q, want 503 unavailable", st, errCode)
	}

	// The identify pre-check answers the same 503 with NOTHING written.
	queued, st, errCode := qaTmdbIdentify(t, client, srv.baseURL, "items", it.ID, strconv.Itoa(qaTmdbFilmAID))
	if st != http.StatusServiceUnavailable || errCode != "unavailable" {
		t.Errorf("dormant identify: HTTP %d code %q, want 503 unavailable", st, errCode)
	}
	if queued {
		t.Errorf("dormant identify reported queued=true — the pre-check must refuse before any write")
	}
	after := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, "Dormant Signal 2021.mkv")
	ids, _ := decodeMap(after.Document, "identifiers")
	if _, present := ids["tmdb_id"]; present {
		t.Errorf("dormant identify landed identifiers.tmdb_id = %v (never write-then-dormant)", ids["tmdb_id"])
	}
	if after.Status != "ready" {
		t.Errorf("dormant identify regressed the row to %q, want ready untouched", after.Status)
	}

	// The aggregate's verdicts: per-binding provided:false on BOTH seeded
	// slots, the ordinary option keys verbatim (nothing secret to redact).
	tvBinding := qaTmdbBindingFor(t, client, srv.baseURL, "tv")
	if v, ok := tvBinding.RequiredSecrets["api_key"]; !ok || v {
		t.Errorf("tv binding required_secrets = %v, want api_key provided:false", tvBinding.RequiredSecrets)
	}
	if tvBinding.Priority == nil || *tvBinding.Priority != 3 {
		t.Errorf("tv binding priority = %v, want the seeded slot 3", tvBinding.Priority)
	}
	var tvOpts map[string]any
	if err := json.Unmarshal(tvBinding.Options, &tvOpts); err != nil {
		t.Fatalf("tv binding options %s: decode: %v", tvBinding.Options, err)
	}
	if _, leak := tvOpts["api_key"]; leak {
		t.Errorf("tv binding options = %v, want no api_key anywhere (nothing was written)", tvOpts)
	}
	if tvOpts["language"] != "en-US" {
		t.Errorf("tv binding options = %v, want the seed's ordinary key served verbatim", tvOpts)
	}
	serialBinding := qaTmdbBindingFor(t, client, srv.baseURL, "serial")
	if v, ok := serialBinding.RequiredSecrets["api_key"]; !ok || v {
		t.Errorf("serial binding required_secrets = %v, want api_key provided:false (per-binding verdicts)", serialBinding.RequiredSecrets)
	}
	if serialBinding.Priority == nil || *serialBinding.Priority != 4 {
		t.Errorf("serial binding priority = %v, want the seeded slot 4", serialBinding.Priority)
	}
}

// --- leg (d): re-anchoring fetches BY the picked id ---

// TestQATmdbItemIdentifyJoint: identify to film A, wait for its anchored run,
// then identify to film B — the strip clears A's namespace, the re-derived run
// fetches BY the picked id (the stub serves a DIFFERENT film there), and the
// namespace rebuilds fresh from B's payload. No search ever fires: the anchor
// is the only route both times.
func TestQATmdbItemIdentifyJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tmdb joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the film fixture cannot be probed (INV4: optional binary)")
	}
	tmp := t.TempDir()
	up := qaTmdbStartUpstream(t)
	srv := qaTmdbStartServer(t, tmp, up.baseURL, qaTmdbDeadUpstream)
	client := &http.Client{Timeout: httpTimeout}
	qaTmdbConfigureSecret(t, client, srv.baseURL, "tv")

	root := qaTmdbWriteFilmLibrary(t, qaTmdbFilmBRel)
	libID := qaTmdbCreateTvLibrary(t, client, srv.baseURL, root, "QA Tmdb Reanchor")
	res := scanLibrary(t, client, srv.baseURL, qaTmdbToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("reanchor scan discovered=%d persisted=%d, want 1/1", res.Discovered, res.Persisted)
	}
	qaSerialWaitSettled(t, client, srv.baseURL, qaTmdbToken, libID)
	it := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, qaTmdbFilmBRel)

	// First anchor: film A.
	if queued, st, _ := qaTmdbIdentify(t, client, srv.baseURL, "items", it.ID, strconv.Itoa(qaTmdbFilmAID)); st != http.StatusAccepted || !queued {
		t.Fatalf("identify A: HTTP %d queued=%v, want 202 queued=true", st, queued)
	}
	first := qaTmdbWaitItemNamespace(t, client, srv.baseURL, libID, qaTmdbFilmBRel, up)
	firstDoc := parseAsyncDoc(t, first.Document)
	if asyncStr(firstDoc.Sources["tmdb"], "description") != "qa film A synopsis — ночной бег через спящий город." {
		t.Fatalf("film A namespace = %v, want film A's payload", firstDoc.Sources["tmdb"])
	}
	snapshotA := len(up.requests())

	// Re-anchor: film B — a DIFFERENT film served under the picked id.
	if queued, st, _ := qaTmdbIdentify(t, client, srv.baseURL, "items", it.ID, strconv.Itoa(qaTmdbFilmBID)); st != http.StatusAccepted || !queued {
		t.Fatalf("identify B: HTTP %d queued=%v, want 202 queued=true", st, queued)
	}
	second := qaTmdbWaitItemNamespace(t, client, srv.baseURL, libID, qaTmdbFilmBRel, up)
	secondDoc := parseAsyncDoc(t, second.Document)
	bns := secondDoc.Sources["tmdb"]
	if asyncStr(bns, "description") != "qa film B synopsis — состав идёт сквозь полдень." {
		t.Errorf("re-anchored namespace = %v, want film B's payload (the rebuild fetched the picked id)", bns)
	}
	btitle, _ := bns["title"].(map[string]any)
	if asyncStr(btitle, "russian") != "Дневной состав" {
		t.Errorf("re-anchored title = %v, want film B's russian title", btitle)
	}
	ids, _ := decodeMap(second.Document, "identifiers")
	if got := asyncInt(ids, "tmdb_id"); got != qaTmdbFilmBID {
		t.Errorf("identifiers.tmdb_id = %v, want %d (the overwrite)", ids["tmdb_id"], qaTmdbFilmBID)
	}
	cast, _ := bns["cast"].([]any)
	if len(cast) != 1 {
		t.Fatalf("re-anchored cast = %v, want film B's credits entry", cast)
	}
	entry, _ := cast[0].(map[string]any)
	if asyncStr(entry, "name") != "Пётр Qa Кондукторов" {
		t.Errorf("re-anchored cast entry = %v, want film B's own credits", entry)
	}

	// The re-derived run's fetches, isolated between the two snapshots:
	// exactly the BY-ID pair for film B — never a search, never film A again.
	delta := up.requests()[snapshotA:]
	gotB, gotBCredits := 0, 0
	for _, r := range delta {
		switch r.path {
		case "/3/movie/" + strconv.Itoa(qaTmdbFilmBID):
			gotB++
		case "/3/movie/" + strconv.Itoa(qaTmdbFilmBID) + "/credits":
			gotBCredits++
		default:
			t.Errorf("re-anchor run fetched %s %s — want only the film-B by-id pair", r.method, r.path)
		}
	}
	if gotB != 1 || gotBCredits != 1 {
		t.Errorf("re-anchor fetches: film-B detail x%d, credits x%d, want exactly one of each", gotB, gotBCredits)
	}
	if n := up.countPath("/3/search/movie") + up.countPath("/3/search/tv"); n != 0 {
		t.Errorf("recording carries %d search fetches, want 0 (an anchored run fetches BY the id)", n)
	}
}

// --- leg (e): the relay descriptor carries the RESOLVED key ---

// TestQATmdbRelayDescriptorJoint: a network-class tmdb failure (the dead
// upstream — connection refused) with the relay live hands out a job whose
// stored plan carries the RESOLVED api key — the server-authored descriptor
// law (client-relayed-fetch + tmdb-enrichment D4). The placeholder
// {server:api_key} must never survive into a descriptor a relay principal can
// claim.
func TestQATmdbRelayDescriptorJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA tmdb joint: skips under -short (builds binaries + subprocesses)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the film fixture cannot be probed (INV4: optional binary)")
	}
	tmp := t.TempDir()
	srv := qaTmdbStartServer(t, tmp, qaTmdbDeadUpstream, qaTmdbDeadUpstream)
	client := &http.Client{Timeout: httpTimeout}
	qaTmdbConfigureSecret(t, client, srv.baseURL, "tv")

	root := qaTmdbWriteFilmLibrary(t, qaTmdbRelayRel)
	libID := qaTmdbCreateTvLibrary(t, client, srv.baseURL, root, "QA Tmdb Relay")
	res := scanLibrary(t, client, srv.baseURL, qaTmdbToken, libID)
	if res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("relay scan discovered=%d persisted=%d, want 1/1", res.Discovered, res.Persisted)
	}
	qaSerialWaitSettled(t, client, srv.baseURL, qaTmdbToken, libID)
	it := qaTmdbItemByRel(t, client, srv.baseURL, qaTmdbToken, libID, qaTmdbRelayRel)

	if queued, st, _ := qaTmdbIdentify(t, client, srv.baseURL, "items", it.ID, strconv.Itoa(qaTmdbRelayID)); st != http.StatusAccepted || !queued {
		t.Fatalf("identify: HTTP %d queued=%v, want 202 queued=true", st, queued)
	}

	// The network-class failure lands the relayed ledger row for (row, tmdb).
	row := qaTmdbWaitTmdbFailure(t, client, srv.baseURL, it.ID)
	if row.Status != "relayed" {
		t.Errorf("failure row status = %q, want relayed (the handoff's loop-safety write)", row.Status)
	}

	// The claim: any authenticated principal (the admin token rides the browse
	// group) — the descriptor's plan must carry the RESOLVED key.
	var claim qaRelayClaim
	if status := doRequest(t, client, http.MethodPost, srv.baseURL+"/api/v1/relay/claim", qaTmdbToken, nil, &claim); status != http.StatusOK {
		t.Fatalf("POST /relay/claim: HTTP %d, want 200", status)
	}
	if claim.Purpose != "enrich" {
		t.Errorf("claim purpose = %q, want enrich", claim.Purpose)
	}
	if len(claim.Plan) != 2 {
		t.Fatalf("claim plan = %+v, want the two-spec anchored plan (detail + credits)", claim.Plan)
	}
	wantURLs := []string{
		qaTmdbDeadUpstream + "/movie/700103?language=ru-RU&api_key=" + qaTmdbAPIKey,
		qaTmdbDeadUpstream + "/movie/700103/credits?language=ru-RU&api_key=" + qaTmdbAPIKey,
	}
	for i, want := range wantURLs {
		if claim.Plan[i].URL != want {
			t.Errorf("plan[%d].url = %q, want the RESOLVED descriptor %q", i, claim.Plan[i].URL, want)
		}
		if claim.Plan[i].Method != http.MethodGet {
			t.Errorf("plan[%d].method = %q, want GET", i, claim.Plan[i].Method)
		}
		if claim.Plan[i].MinIntervalMS != 250 {
			t.Errorf("plan[%d].min_interval_ms = %d, want the tmdb pacing 250", i, claim.Plan[i].MinIntervalMS)
		}
	}
	raw, err := json.Marshal(claim)
	if err != nil {
		t.Fatalf("re-marshal claim: %v", err)
	}
	if strings.Contains(string(raw), "{server:api_key}") || strings.Contains(string(raw), "server:") {
		t.Errorf("descriptor bytes %s carry an unresolved placeholder — the secret never resolved", raw)
	}
}
